const anchorKeys=new Set(["codepointEndExclusive", "codepointStart", "endCodePointExclusive", "endUTF8ByteExclusive", "field", "fullFieldSHA256", "literalToken", "occurrenceCountInFullField", "occurrenceIndex", "occurrenceIndexZeroBased", "occurrenceOrdinalOneBased", "occurrences", "offsetUnit", "startCodePoint", "startUTF8Byte", "text", "token", "tokenSHA256", "totalExactNonOverlappingOccurrences", "utf8EndExclusive", "utf8Start"]), occurrenceKeys=new Set(["codepointEndExclusive", "codepointStart", "endCodePointExclusive", "endExclusive", "endUTF8ByteExclusive", "occurrenceCountInFullField", "occurrenceIndex", "occurrenceIndexZeroBased", "occurrenceOrdinalOneBased", "start", "startCodePoint", "startUTF8Byte", "tokenSHA256", "utf8EndExclusive", "utf8Start"]);
const anchorStrings=new Set(['field','fullFieldSHA256','literalToken','offsetUnit','text','token','tokenSHA256']);
function anchorSchema(a,occurrence=false){
 assert(a&&typeof a==='object'&&!Array.isArray(a),'Public anchor/occurrence object');
 for(const [key,value]of Object.entries(a)){
  assert((occurrence?occurrenceKeys:anchorKeys).has(key),'Public anchor/occurrence field allowlist');
  if(key==='occurrences'){assert(Array.isArray(value)&&value.length>0,'Anchor occurrence inventory');value.forEach(o=>anchorSchema(o,true));}
  else if(anchorStrings.has(key))assert(typeof value==='string','Public anchor string');
  else assert(Number.isInteger(value)&&value>=0,'Public anchor coordinate/count');
 }
}
const assert=(ok,msg)=>{if(!ok)throw Error(msg);};
export function assertAudienceSafe(v){
 const bad=/\/mnt\/[a-z]\/|\/root\/|[A-Za-z]:\\|qualifiedEnglish|acceptance_counter|hidden_private|English_qualified_total_private_only|INDEPENDENT-PRIVATE-ORACLE/;
 const privateKeys=new Set(['bindingRole','primaryPointer','attachmentState','activeBinding']);
 const processValue=/proposedEnglish_in_new_private_proposal|REBOUND_PREPARATION_ONLY|PROPOSAL_AWAITING_|PRIVATE_PROCESS|INDEPENDENTLY_REVIEWED|\/proposals\//;
 function scan(x){if(typeof x==='string')assert(!bad.test(x)&&!processValue.test(x),'Private path/workflow leak');else if(x&&typeof x==='object')for(const [k,v]of Object.entries(x)){assert(!privateKeys.has(k),'Private workflow key: '+k);scan(k);scan(v);}}
 // Decode JSON first: literal colon/newline source text is not a Windows drive path.
 if(typeof v==='string'){let parsed;try{parsed=JSON.parse(v);}catch{scan(v);return v;}scan(parsed);}else scan(v);return v;
}
